'use strict';
// Requirement: PRD-075 (docs/PRD.md).
// tests/tools/gen-dc-profile.test.js — schema/dctap.csv is the Dublin Core Tabular
// Application Profile of the table in AGSC-05-26, generated by tools/gen-dc-profile
// from `schema/item.schema.json` and that table. The suite fails when the committed
// file is not what the tool generates (the "documentation check" of AGSC-05-26), and
// reads the file back as CSV to check it against the table and the schema.
//
// Deterministic: reads the repository and temporary copies; no clock, no network.

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { describe, it } = require('node:test');
const fc = require('fast-check');

const { REPO, capture, codes, envelope, tmpdir, tool } = require('./helpers');

const generator = tool('gen-dc-profile');
const COLUMNS = ['shapeID', 'shapeLabel', 'propertyID', 'propertyLabel', 'mandatory', 'repeatable',
  'valueNodeType', 'valueDataType', 'valueShape', 'valueConstraint', 'valueConstraintType', 'note'];

/** The rows of a CSV text as objects keyed by the header; a small RFC 4180 reader, independent of the tool. */
function readCsv(text) {
  const rows = [];
  let row = [''];
  let quoted = false;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { row[row.length - 1] += '"'; i += 1; } else if (c === '"') quoted = false;
      else row[row.length - 1] += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') row.push('');
    else if (c === '\n') { rows.push(row); row = ['']; } else row[row.length - 1] += c;
  }
  const [header, ...body] = rows;
  return { header, rows: body.map((cells) => Object.fromEntries(header.map((name, i) => [name, cells[i]]))) };
}

/** The propertyIDs of the AGSC-05-26 table, read from the specification by a pattern of its own. */
function tablePropertyIds() {
  const spec = fs.readFileSync(path.join(REPO, 'spec', '05-graph.md'), 'utf8');
  const start = spec.indexOf('| Frontmatter key |');
  const lines = spec.slice(start).split('\n');
  const end = lines.findIndex((line) => !line.startsWith('|'));
  return lines.slice(2, end).map((line) => line.split('|')[3].trim().replace(/`/gu, ''));
}

describe('tools/gen-dc-profile', () => {
  it('the committed schema/dctap.csv is exactly what the tool generates (--check)', () => {
    const r = capture('gen-dc-profile', ['--check']);
    assert.equal(r.code, 0, r.err);
    assert.match(r.out, /^schema\/dctap\.csv: current \(\d+ rows\)\n$/u);
  });

  it('the header is the twelve DCTAP elements in order, and propertyID is filled in every row', () => {
    const { header, rows } = readCsv(fs.readFileSync(path.join(REPO, 'schema', 'dctap.csv'), 'utf8'));
    assert.deepEqual(header, COLUMNS);
    assert.ok(rows.length > 0);
    for (const row of rows) assert.notEqual(row.propertyID, '', JSON.stringify(row));
  });

  it('every property of the AGSC-05-26 table is a row, and nothing else is', () => {
    const { rows } = readCsv(fs.readFileSync(path.join(REPO, 'schema', 'dctap.csv'), 'utf8'));
    const wanted = new Set(tablePropertyIds());
    assert.ok(wanted.size >= 20, 'the table was not found');
    assert.deepEqual(new Set(rows.map((row) => row.propertyID)), wanted);
  });

  it('the shapes are the four subjects of the table, and a Bundle-and-item row is in both', () => {
    const { rows } = readCsv(fs.readFileSync(path.join(REPO, 'schema', 'dctap.csv'), 'utf8'));
    assert.deepEqual([...new Set(rows.map((row) => row.shapeID))], ['item', 'bundle', 'source', 'review']);
    const shapesOf = (id) => rows.filter((row) => row.propertyID === id).map((row) => row.shapeID);
    assert.deepEqual(shapesOf('schema:license'), ['item', 'bundle']);
    assert.deepEqual(shapesOf('asc:grade'), ['source']);
    assert.deepEqual(shapesOf('asc:verifiedBy'), ['review']);
  });

  it('a closed list in the item schema is a picklist, and only a closed list is a constraint', () => {
    const { rows } = readCsv(fs.readFileSync(path.join(REPO, 'schema', 'dctap.csv'), 'utf8'));
    const row = (id) => rows.find((r) => r.propertyID === id);
    const schema = JSON.parse(fs.readFileSync(path.join(REPO, 'schema', 'item.schema.json'), 'utf8'));
    assert.equal(row('asc:status').valueConstraintType, 'picklist');
    assert.equal(row('asc:status').valueConstraint, schema.properties.status.enum.join(' '));
    assert.equal(row('asc:origin').valueConstraint, schema.$defs.prov.properties.origin.enum.join(' '));
    assert.equal(row('asc:grade').valueConstraint, schema.$defs.source.properties.grade.enum.join(' '));
    assert.equal(row('schema:additionalType').valueConstraint, schema.properties.domain_role.enum.join(' '));
    for (const free of ['dcterms:created', 'asc:model', 'schema:license']) {
      assert.equal(row(free).valueConstraint, '', free);
      assert.equal(row(free).valueConstraintType, '', free);
    }
  });

  it('a datatype property is a literal that is not mandatory and not repeatable, with its datatype', () => {
    const { rows } = readCsv(fs.readFileSync(path.join(REPO, 'schema', 'dctap.csv'), 'utf8'));
    for (const r of rows) {
      assert.equal(r.valueNodeType, 'literal');
      assert.equal(r.mandatory, 'false');
      assert.equal(r.repeatable, 'false');
      assert.match(r.valueDataType, /^xsd:(string|dateTime)$/u);
    }
  });

  it('--json is the AGSC-09-11 envelope of the tool, and a current file has no finding', () => {
    const r = envelope('gen-dc-profile', ['--check']);
    assert.equal(r.json.verb, 'gen-dc-profile');
    assert.equal(r.json.schema, 'agsc.diagnostics.v1');
    assert.equal(r.json.status, 'pass');
    assert.deepEqual(r.json.findings, []);
  });

  it('--help prints the usage; an unknown flag or a second root is usage, exit 2', () => {
    const help = capture('gen-dc-profile', ['--help']);
    assert.equal(help.code, 0);
    assert.match(help.out, /^gen-dc-profile \[--check\]/u);
    assert.equal(capture('gen-dc-profile', ['--nope']).code, 2);
    assert.equal(capture('gen-dc-profile', ['a', 'b']).code, 2);
  });

  it('a stale file fails --check with AGSC-E602, a write makes it current, and the write is idempotent', () => {
    const dir = tmpdir();
    for (const rel of ['schema/item.schema.json', 'spec/05-graph.md', 'package.json']) {
      fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
      fs.copyFileSync(path.join(REPO, rel), path.join(dir, rel));
    }
    fs.writeFileSync(path.join(dir, 'schema', 'dctap.csv'), 'edited by hand\n');
    const stale = envelope('gen-dc-profile', ['--check', dir]);
    assert.equal(stale.code, 1);
    assert.deepEqual(codes(stale.json), ['AGSC-E602']);
    assert.equal(capture('gen-dc-profile', [dir]).code, 0);
    const written = fs.readFileSync(path.join(dir, 'schema', 'dctap.csv'), 'utf8');
    assert.equal(written, fs.readFileSync(path.join(REPO, 'schema', 'dctap.csv'), 'utf8'));
    assert.equal(capture('gen-dc-profile', [dir]).code, 0);
    assert.equal(fs.readFileSync(path.join(dir, 'schema', 'dctap.csv'), 'utf8'), written);
    assert.equal(capture('gen-dc-profile', ['--check', dir]).code, 0);
  });

  it('a missing input, a table that is not there and a schema that is not JSON are each AGSC-E901 or AGSC-E201, exit 1', () => {
    const dir = tmpdir();
    assert.deepEqual(codes(envelope('gen-dc-profile', [dir]).json), ['AGSC-E901']);
    fs.mkdirSync(path.join(dir, 'schema'));
    fs.mkdirSync(path.join(dir, 'spec'));
    fs.writeFileSync(path.join(dir, 'schema', 'item.schema.json'), '{ not json');
    fs.writeFileSync(path.join(dir, 'spec', '05-graph.md'), '# no table here\n');
    assert.deepEqual(codes(envelope('gen-dc-profile', [dir]).json), ['AGSC-E201', 'AGSC-E901']);
    assert.equal(fs.existsSync(path.join(dir, 'schema', 'dctap.csv')), false);
  });

  it('property: a field is quoted exactly when RFC 4180 needs it, and reads back unchanged', () => {
    fc.assert(fc.property(fc.array(fc.string({ maxLength: 12 }), { maxLength: 6, minLength: 1 }), (cells) => {
      const line = generator.csvLine(cells);
      assert.deepEqual(readCsv(`h\n${line}\n`).rows.length, 1);
      const back = readCsv(`${cells.map((_, i) => `c${i}`).join(',')}\n${line}\n`).rows[0];
      assert.deepEqual(cells.map((_, i) => back[`c${i}`]), cells);
    }), { numRuns: 200, seed: 5026 });
  });
});
